function editorV222(){const s=currentStyleV222(),fonts=['Vazirmatn','Estedad','Sahel','Shabnam','Gandom','Noto Naskh Arabic','Noto Kufi Arabic','Amiri','Lalezar','Cinzel','Cinzel Decorative','Cormorant Garamond','Cormorant SC','EB Garamond','Libre Baskerville','Playfair Display','Merriweather','Crimson Text','Lora','Noto Serif Arabic','Scheherazade New','Markazi Text','Great Vibes','Marcellus','Spectral','Bodoni Moda'],themes=[['ornate_baptism',L('قاب تعمید کلاسیک آبی–طلایی','Ornate baptism','Ukrasno krštenje')],['official_watermark',L('رسمی با واترمارک','Official watermark','Službeni vodeni žig')],['classic_gold_v222',L('طلایی کلاسیک','Classic gold','Klasično zlato')],['royal_blue_v222',L('آبی سلطنتی','Royal blue','Kraljevsko plava')],['emerald_v222',L('زمردی خدمتی','Emerald ministry','Smaragdna')],['water_baptism_v222',L('آب تعمید','Baptism water','Voda krštenja')],['letter_formal_v222',L('نامه رسمی سربرگ‌دار','Formal letterhead','Službeno pismo')],['minimal_v222',L('مینیمال','Minimal','Minimalno')],['ornate_blue_gold_v223',L('قاب تشریفاتی آبی–طلایی جدید','New ornate blue–gold','Novi plavo-zlatni okvir')],['silver_official_v223',L('رسمی نقره‌ای','Official silver','Službeno srebrno')],['parchment_v223',L('کاغذ کلاسیک','Classic parchment','Klasični pergament')],['covenant_gold_v224',L('عهد طلایی','Covenant gold','Zlatni savez')],['royal_marble_v224',L('مرمر سلطنتی','Royal marble','Kraljevski mramor')],['baptism_wave_v224',L('موج تعمید','Baptism waves','Valovi krštenja')],['ministry_blue_v224',L('خدمت آبی رسمی','Formal ministry blue','Službeno plava')]];return `<section class="panel-card doc-v222-editor"><div class="req-head"><div><h3>🎨 ${L('استودیوی حرفه‌ای مدارک و نامه‌ها','Professional Document Studio','Profesionalni studio dokumenata')}</h3><p class="muted small">${L('برای QR واقعی ابتدا مدرک یا نامه را صادر کن؛ سپس Preview را باز کن و با گوشی اسکن کن. هر صدور، QR و کد اعتبار کاملاً متفاوت دارد.','Issue the document first for a real QR, then open Preview and scan it with a phone. Every issued record has a different QR and verification code.','Prvo izdajte dokument za stvarni QR; svaki dokument ima jedinstven QR.')}</p></div></div><details open><summary>${L('قالب، لوگو و اطلاعات کلیسا','Template, logo and church details','Predložak i podaci crkve')}</summary><div class="doc-v222-editor-body"><div class="doc-v222-grid"><label>${L('جهت صفحه','Page layout','Orijentacija')}<select onchange="nh7DocSetV222('layout',this.value)"><option value="portrait" ${nh7DocDraftV222.layout==='portrait'?'selected':''}>A4 ${L('عمودی','Portrait','Okomito')}</option><option value="landscape" ${nh7DocDraftV222.layout==='landscape'?'selected':''}>A4 ${L('افقی','Landscape','Vodoravno')}</option></select></label><label>${L('تم و قاب','Theme / frame','Tema / okvir')}<select onchange="nh7DocSetV222('theme',this.value)">${themes.map(([v,t])=>`<option value="${v}" ${nh7DocDraftV222.theme===v?'selected':''}>${E(t)}</option>`).join('')}</select></label><label>${L('شدت واترمارک','Watermark opacity','Jačina vodenog žiga')}<input type="range" min="0" max="0.14" step="0.005" value="${nh7DocDraftV222.watermarkOpacity}" oninput="nh7DocSetV222('watermarkOpacity',this.value)"></label></div><div class="doc-v222-grid two"><label>${L('لوگوی مدرک','Document logo','Logo dokumenta')}<input type="file" accept="image/*" onchange="nh7UploadDocImageV222(this,'logo')"></label><label>${L('شکل لوگو','Logo shape','Oblik logotipa')}<select onchange="nh7DocSetV222('logoCircle',this.value==='circle')"><option value="normal" ${!nh7DocDraftV222.logoCircle?'selected':''}>${L('عادی','Normal','Normalno')}</option><option value="circle" ${nh7DocDraftV222.logoCircle?'selected':''}>${L('گرد','Circular','Kružno')}</option></select></label><label>${L('ترکیب با پس‌زمینه','Blend with background','Spajanje s pozadinom')}<select onchange="nh7DocSetV222('logoBlend',this.value)"><option value="normal" ${nh7DocDraftV222.logoBlend!=='multiply'?'selected':''}>${L('عادی','Normal','Normalno')}</option><option value="multiply" ${nh7DocDraftV222.logoBlend==='multiply'?'selected':''}>${L('حذف نمای سفید با ترکیب رنگ','Blend white background','Spoji bijelu pozadinu')}</option></select></label><label>${L('رنگ زمینه لوگو','Logo background color','Pozadina logotipa')}<input type="color" value="${E(nh7DocDraftV222.logoBg||'#ffffff')}" oninput="nh7DocSetV222('logoBg',this.value)"></label><label>${L('جای لوگو','Logo position','Položaj logotipa')}<select onchange="nh7DocSetV222('logoPosition',this.value)"><option value="right" ${nh7DocDraftV222.logoPosition==='right'?'selected':''}>${L('بالا راست','Top right','Gore desno')}</option><option value="center" ${nh7DocDraftV222.logoPosition==='center'?'selected':''}>${L('بالا وسط','Top center','Gore sredina')}</option></select></label><label>${L('اندازه لوگو','Logo size','Veličina logotipa')}<input type="range" min="45" max="180" value="${Number(nh7DocDraftV222.logoSize||94)}" oninput="nh7DocSetV222('logoSize',this.value)"></label><label>${L('نام کلیسا','Church name','Naziv crkve')}<input value="${E(nh7DocDraftV222.church.name)}" oninput="nh7DocDraftV222.church.name=this.value"></label><label>${L('آدرس','Address','Adresa')}<input value="${E(nh7DocDraftV222.church.address)}" oninput="nh7DocDraftV222.church.address=this.value"></label><label>Email<input value="${E(nh7DocDraftV222.church.email)}" oninput="nh7DocDraftV222.church.email=this.value"></label><label>${L('تلفن','Phone','Telefon')}<input value="${E(nh7DocDraftV222.church.phone)}" oninput="nh7DocDraftV222.church.phone=this.value"></label><label>Website<input value="${E(nh7DocDraftV222.church.website)}" oninput="nh7DocDraftV222.church.website=this.value"></label></div></div></details><details open><summary>${L('عکس و تنظیم دقیق چهره','Photo and face positioning','Fotografija i položaj lica')}</summary><div class="doc-v222-editor-body"><input type="file" accept="image/*" onchange="nh7UploadDocImageV222(this,'photo')"><div class="doc-v222-photo-stage">${nh7DocDraftV222.photoUrl?`<img src="${E(nh7DocDraftV222.photoUrl)}" style="object-position:${N(nh7DocDraftV222.photo.x)}% ${N(nh7DocDraftV222.photo.y)}%;transform:scale(${N(nh7DocDraftV222.photo.zoom)||1})">`:`<div class="doc-v222-photo-empty">${L('عکس را آپلود کن','Upload a photo','Prenesite fotografiju')}</div>`}</div><div class="doc-v222-grid"><label>${L('چپ و راست','Left / right','Lijevo / desno')}<input type="range" min="0" max="100" value="${N(nh7DocDraftV222.photo.x)}" oninput="nh7DocPhotoV222('x',this.value)"></label><label>${L('بالا و پایین','Up / down','Gore / dolje')}<input type="range" min="0" max="100" value="${N(nh7DocDraftV222.photo.y)}" oninput="nh7DocPhotoV222('y',this.value)"></label><label>${L('زوم','Zoom','Zum')}<input type="range" min="1" max="3" step="0.05" value="${N(nh7DocDraftV222.photo.zoom)||1}" oninput="nh7DocPhotoV222('zoom',this.value)"></label><label>${L('اندازه قاب عکس','Photo frame size','Veličina fotografije')}<input type="range" min="65" max="190" value="${N(nh7DocDraftV222.photo.size)||115}" oninput="nh7DocPhotoV222('size',this.value)"></label></div></div></details><details open><summary>${L('فونت جداگانه هر بخش','Per-section font and formatting','Font svakog dijela')}</summary><div class="doc-v222-editor-body"><div class="doc-v222-style-toolbar"><label>${L('بخش متن','Text element','Dio teksta')}<select onchange="nh7DocStyleTargetV222(this.value)">${[['title',L('عنوان اصلی','Main title','Glavni naslov')],['designation',L('زیرعنوان','Subtitle','Podnaslov')],['name',L('نام شخص','Recipient name','Ime osobe')],['body',L('متن بدنه','Body','Tekst')],...Array.from({length:8},(_,i)=>['bodyLine'+(i+1),L('سطر '+(i+1)+' متن','Body line '+(i+1),'Redak teksta '+(i+1))]),['fields',L('فیلدها','Fields','Polja')],['church',L('نام و اطلاعات کلیسا','Church heading','Zaglavlje crkve')],['signature',L('متن امضا','Signature text','Tekst potpisa')],['verification',L('QR و اعتبارسنجی','QR and verification','QR i provjera')],['meta',L('شماره و اطلاعات پایین','Footer/meta','Podnožje')]].map(([v,t])=>`<option value="${v}" ${nh7DocDraftV222.styleTarget===v?'selected':''}>${E(t)}</option>`).join('')}</select></label><label>${L('فونت','Font','Font')}<select onchange="nh7DocStyleV222('font',this.value)">${fonts.map(f=>`<option value="${E(f)}" ${s.font===f?'selected':''}>${E(f)}</option>`).join('')}</select></label><label>${L('اندازه','Size','Veličina')}<input type="number" min="7" max="70" value="${N(s.size)}" onchange="nh7DocStyleV222('size',this.value)"></label><label>${L('رنگ متن','Text color','Boja teksta')}<input type="color" value="${E(s.color||'#1e293b')}" oninput="nh7DocStyleV222('color',this.value)"></label><button class="doc-v222-toggle ${s.bold?'active':''}" onclick="nh7DocStyleV222('bold',${!s.bold})"><b>B</b></button><button class="doc-v222-toggle ${s.italic?'active':''}" onclick="nh7DocStyleV222('italic',${!s.italic})"><i>I</i></button><button class="doc-v222-toggle ${s.underline?'active':''}" onclick="nh7DocStyleV222('underline',${!s.underline})"><u>U</u></button><select onchange="nh7DocStyleV222('align',this.value)"><option value="start" ${s.align==='start'?'selected':''}>${L('راست/شروع','Start','Početak')}</option><option value="center" ${s.align==='center'?'selected':''}>${L('وسط','Center','Sredina')}</option><option value="end" ${s.align==='end'?'selected':''}>${L('چپ/پایان','End','Kraj')}</option></select><label>${L('بالا / پایین','Move up / down','Pomak gore / dolje')}<input type="range" min="-80" max="120" value="${Number(s.offsetY||0)}" oninput="nh7DocStyleV222('offsetY',this.value)"></label><label>${L('فاصله خطوط','Line height','Prored')}<input type="range" min="0.9" max="2.5" step="0.05" value="${Number(s.lineHeight||1.45)}" oninput="nh7DocStyleV222('lineHeight',this.value)"></label><label>${L('فاصله حروف','Letter spacing','Razmak slova')}<input type="range" min="-1" max="8" step="0.25" value="${Number(s.letterSpacing||0)}" oninput="nh7DocStyleV222('letterSpacing',this.value)"></label></div><div class="doc-v222-font-preview" style="${styleTextV222(s)}">${L('نمونه نمایش فونت و اندازه متن','Font and size preview','Pregled fonta i veličine')}</div></div></details><details open><summary>✍ ${L('امضا با قلم iPad','Sign with iPad Pencil','Potpis Apple Pencilom')}</summary><div class="doc-v222-editor-body"><canvas id="nh7_signature_pad_v222" class="doc-v222-signature-pad"></canvas><div class="actions"><button class="btn primary" onclick="nh7SaveSignatureV222()">✓ ${L('ذخیره امضا','Save signature','Spremi potpis')}</button><button class="btn ghost" onclick="nh7ClearSignatureV222()">${L('پاک‌کردن','Clear','Očisti')}</button></div></div></details><div class="doc-v222-preview-actions"><button class="btn primary" onclick="nh7OpenFullPreviewV222()">👁 ${L('پیش‌نمایش تمام‌صفحه','Full-screen preview','Pregled preko cijelog zaslona')}</button><button class="btn secondary" onclick="nh7SaveIssuedDesignV222()">💾 ${L('ذخیره طراحی روی مدرک انتخاب‌شده','Save design to selected issued document','Spremi dizajn')}</button><button class="btn ghost" onclick="nh7CheckQrV222()">📱 ${L('بازکردن صفحه اعتبارسنجی','Open verification page','Otvori provjeru')}</button></div><div class="doc-v222-qr-help">${L('برای کنترل با گوشی: مدرک را صادر کن، از فهرست مدارک صادرشده آن را انتخاب کن، Preview تمام‌صفحه را باز کن و QR را با دوربین گوشی اسکن کن. تا وقتی صفحه اعتبارسنجی نام، شماره و وضعیت معتبر را نشان نداده، چاپ نکن.','To check with a phone: issue the document, select it from issued documents, open full preview, and scan its QR. Do not print until the verification page shows the correct name, number, and valid status.','Za provjeru izdajte dokument, otvorite puni pregled i skenirajte QR.')}</div></section>`}
window.nh7OpenFullPreviewV222=()=>{let modal=document.getElementById('nh7_doc_preview_modal');if(!modal){modal=document.createElement('div');modal.id='nh7_doc_preview_modal';modal.className='doc-v222-preview-modal';document.body.appendChild(modal)}let data=nh7CertificatePreviewMode==='manual'?nh7CertificateDataFromManual():nh7CertificatePreviewMode==='issued'&&selectedIssuedRowV222()?nh7CertificateDataFromRow(selectedIssuedRowV222()):nh7CertificateDataFromSchool(nh7SchoolCertificateEntry?.(),null);modal.innerHTML=`<div class="doc-v222-preview-top"><button class="doc-v222-close" onclick="nh7CloseFullPreviewV222()" aria-label="Close">×</button><button class="btn ghost" onclick="nh7CloseFullPreviewV222()">‹ ${L('بازگشت به پنل','Back to panel','Natrag na panel')}</button><button class="btn primary" onclick="nh7PrintFullPreviewV222()">🖨 ${L('چاپ / PDF','Print / PDF','Ispis / PDF')}</button><button class="btn secondary" onclick="nh7CheckQrV222()">📱 QR</button></div><div id="nh7_full_preview_target" class="certificate-shell">${docCanvasV222(data)}</div>`;hydrateQrsV222(modal)};
window.nh7CloseFullPreviewV222=()=>document.getElementById('nh7_doc_preview_modal')?.remove();
window.nh7PrintFullPreviewV222=()=>{const row=selectedIssuedRowV222();if(!row||nh7CertificatePreviewMode!=='issued'){alert(L('برای چاپ رسمی دارای QR، ابتدا مدرک را صادر و از فهرست صادرشده انتخاب کن.','Issue and select the document before official printing with QR.','Prvo izdajte i odaberite dokument.'));return}const t=document.getElementById('nh7_full_preview_target');t?.classList.add('certificate-print-target');window.print();setTimeout(()=>t?.classList.remove('certificate-print-target'),600)};
printCurrentCertificate=function(){
  const row=selectedIssuedRowV222();
  if(!row||nh7CertificatePreviewMode!=='issued'){
    alert(L('برای چاپ رسمی همراه QR، ابتدا سند را صادر کن و از فهرست «مدارک صادرشده» انتخاب کن.','For official printing with QR, issue the document and select it from Issued Documents first.','Za službeni ispis prvo izdajte i odaberite dokument.'));
    return;
  }
  nh7OpenFullPreviewV222();
};
window.nh7CheckQrV222=()=>{const row=selectedIssuedRowV222(),url=uniqueQrUrlV222(row);if(!url){alert(L('این فقط پیش‌نویس است. ابتدا مدرک یا نامه را صادر کن تا QR یکتای واقعی ساخته شود.','This is a draft. Issue it first to create a real unique QR.','Ovo je nacrt; prvo izdajte dokument.'));return}window.open(url,'_blank','noopener')};
window.nh7SaveIssuedDesignV222=async()=>{const row=selectedIssuedRowV222();if(!row){alert(L('ابتدا یک مدرک صادرشده را انتخاب کن.','Select an issued document first.','Odaberite izdani dokument.'));return}try{if(signaturePadV222)await saveSignatureV222();const payload={layout:nh7DocDraftV222.layout,theme_code:nh7DocDraftV222.theme,logo_url:nh7DocDraftV222.logoUrl,photo_url:nh7DocDraftV222.photoUrl,signature_url:nh7DocDraftV222.signatureUrl,photo_position:nh7DocDraftV222.photo,church_info:nh7DocDraftV222.church,design:{theme:nh7DocDraftV222.theme,layout:nh7DocDraftV222.layout,logoUrl:nh7DocDraftV222.logoUrl,photoUrl:nh7DocDraftV222.photoUrl,signatureUrl:nh7DocDraftV222.signatureUrl,photo:nh7DocDraftV222.photo,church:nh7DocDraftV222.church,styles:nh7DocDraftV222.styles,watermarkOpacity:nh7DocDraftV222.watermarkOpacity,logoCircle:nh7DocDraftV222.logoCircle,logoBlend:nh7DocDraftV222.logoBlend,logoBg:nh7DocDraftV222.logoBg,logoPosition:nh7DocDraftV222.logoPosition,logoSize:nh7DocDraftV222.logoSize},updated_at:new Date().toISOString()};await authFetch('/rest/v1/school_certificates?id=eq.'+encodeURIComponent(row.id),{method:'PATCH',body:JSON.stringify(payload)});await loadAll(true);alert(L('طراحی روی همین مدرک ذخیره شد.','Design saved to this document.','Dizajn je spremljen.'))}catch(e){alert(e.message)}};
window.nh7IssueOfficialLetterV222=async()=>{const d=officialLetterDraftV222;if(!d.user_name.trim()||!d.body_fa.trim()&&!d.body_en.trim()&&!d.body_hr.trim()){alert(L('نام گیرنده و متن نامه را کامل کن.','Enter recipient and letter body.','Unesite primatelja i tekst.'));return}if(!confirm(L('نامه رسمی صادر شود و QR یکتا ساخته شود؟','Issue this official letter with a unique QR?','Izdati službeno pismo s jedinstvenim QR-om?')))return;try{if(signaturePadV222)await saveSignatureV222();const row=await adminRpc('nh7_admin_issue_document_v222',{p_document:Object.assign({},d,{certificate_type:'official_letter',layout:'portrait',theme_code:'letter_formal_v222',logo_url:nh7DocDraftV222.logoUrl,photo_url:nh7DocDraftV222.photoUrl,signature_url:nh7DocDraftV222.signatureUrl,photo_position:nh7DocDraftV222.photo,church_info:nh7DocDraftV222.church,design:{styles:nh7DocDraftV222.styles,watermarkOpacity:nh7DocDraftV222.watermarkOpacity,theme:'letter_formal_v222',layout:'portrait',logoUrl:nh7DocDraftV222.logoUrl,photoUrl:nh7DocDraftV222.photoUrl,signatureUrl:nh7DocDraftV222.signatureUrl,photo:nh7DocDraftV222.photo,church:nh7DocDraftV222.church,logoCircle:nh7DocDraftV222.logoCircle,logoBlend:nh7DocDraftV222.logoBlend,logoBg:nh7DocDraftV222.logoBg,logoPosition:nh7DocDraftV222.logoPosition,logoSize:nh7DocDraftV222.logoSize}})});const r=Array.isArray(row)?row[0]:row;await loadAll(true);if(r?.id){nh7SelectedCertificateId=r.id;nh7CertificatePreviewMode='issued'}render();alert(L('نامه رسمی صادر شد. اکنون Preview را باز و QR را با گوشی بررسی کن.','Official letter issued. Open Preview and scan its QR.','Službeno pismo je izdano.'))}catch(e){alert(e.message)}};
window.nh7OfficialLetterDraftV222=(key,val)=>{officialLetterDraftV222[key]=val};
function officialLetterFormV222(){const d=officialLetterDraftV222;return `<section class="panel-card doc-v222-official-form"><h3>🏛 ${L('صدور نامه رسمی قابل‌اعتبارسنجی','Issue a verifiable official letter','Izdaj provjerljivo službeno pismo')}</h3><p class="muted small">${L('هر نامه شماره، QR، کد اعتبار و صفحه رسمی مخصوص خودش را دارد و با نامه دیگر یکسان نیست.','Every letter receives its own number, QR, verification code, and public validation page.','Svako pismo ima vlastiti broj, QR i kod provjere.')}</p><div class="grid2"><input value="${E(d.user_name)}" oninput="nh7OfficialLetterDraftV222('user_name',this.value)" placeholder="${L('نام شخص / اداره گیرنده','Recipient person / authority','Primatelj')}"><input class="ltr" value="${E(d.user_email)}" oninput="nh7OfficialLetterDraftV222('user_email',this.value)" placeholder="Email (optional)"><input type="date" value="${E(d.issue_date)}" onchange="nh7OfficialLetterDraftV222('issue_date',this.value)"><input value="${E(d.place)}" oninput="nh7OfficialLetterDraftV222('place',this.value)" placeholder="${L('محل صدور','Place of issue','Mjesto izdavanja')}"></div><div class="grid3"><input value="${E(d.title_fa)}" oninput="nh7OfficialLetterDraftV222('title_fa',this.value)" placeholder="عنوان فارسی"><input value="${E(d.title_en)}" oninput="nh7OfficialLetterDraftV222('title_en',this.value)" placeholder="English title"><input value="${E(d.title_hr)}" oninput="nh7OfficialLetterDraftV222('title_hr',this.value)" placeholder="Hrvatski naslov"></div><div class="grid3"><textarea oninput="nh7OfficialLetterDraftV222('body_fa',this.value)" placeholder="متن فارسی">${E(d.body_fa)}</textarea><textarea oninput="nh7OfficialLetterDraftV222('body_en',this.value)" placeholder="English body">${E(d.body_en)}</textarea><textarea oninput="nh7OfficialLetterDraftV222('body_hr',this.value)" placeholder="Hrvatski tekst">${E(d.body_hr)}</textarea></div><div class="grid2"><select onchange="nh7OfficialLetterDraftV222('language',this.value)"><option value="fa" ${d.language==='fa'?'selected':''}>فارسی</option><option value="en" ${d.language==='en'?'selected':''}>English</option><option value="hr" ${d.language==='hr'?'selected':''}>Hrvatski</option></select><input value="${E(d.approved_by)}" oninput="nh7OfficialLetterDraftV222('approved_by',this.value)" placeholder="Approved by"></div><button class="btn primary" onclick="nh7IssueOfficialLetterV222()">✓ ${L('صدور نامه و ساخت QR یکتا','Issue letter and unique QR','Izdaj pismo i QR')}</button></section>`}
const previousRenderCertificatesV222=renderCertificates;
renderCertificates=function(){return editorV222()+officialLetterFormV222()+previousRenderCertificatesV222()};
const previousSelectIssuedV222=nh7SelectIssuedCertificate;
